[IO.File]::WriteAllText((Join-Path $PWD 'shared/notes.txt'), "one directory, one surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'worker.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# One test worker: its own surl on a free port over its own directory, its own tests, its own`n# stop. Nothing is shared with another worker but the surl binary.`n# Usage: sh worker.sh <worker number> [<password the tests log in with>]`nn=`$1; password=`${2:-s3cret}; dir=work/`$n`nrm -rf `"`$dir`" && mkdir -p `"`$dir/site`"`nprintf 'worker %s\n' `"`$n`" > `"`$dir/site/whoami.txt`"`n: > `"`$dir/listening.txt`"`nsurl --directory `"`$dir/site`" --user tester:s3cret --allow-uploads http://127.0.0.1:0/ \`n  > `"`$dir/listening.txt`" 2> `"`$dir/surl.log`" &`npid=`$!`n`ntries=0`nuntil grep -q '^Listening on ' `"`$dir/listening.txt`"; do`n  if ! kill -0 `"`$pid`" 2>/dev/null; then wait `"`$pid`"; exit; fi`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 100 ]; then kill `"`$pid`"; exit 1; fi`n  sleep 0.1`ndone`nurl=`$(sed -n 's|^Listening on ||p' `"`$dir/listening.txt`" | tr -d '\r')`necho `"`$url`" | sed 's|.*:\([0-9]*\)/`$|\1|' > `"`$dir/port`"`n`n# The tests: upload a result under the name every worker uses, then read it and whoami.txt back.`nprintf 'result of worker %s\n' `"`$n`" > `"`$dir/result.txt`"`nget=`"curl -fsS --digest -u tester:`$password`"`n`$get -T `"`$dir/result.txt`" `"`${url}result.txt`" &&`n  result=`$(`$get `"`${url}result.txt`") && whoami=`$(`$get `"`${url}whoami.txt`")`ntests=`$?`n[ `"`$tests`" -ne 0 ] || echo `"worker `$n: `$whoami, `$result`"`n`nkill `"`$pid`" 2>/dev/null; wait `"`$pid`" 2>/dev/null`nexit `"`$tests`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'run-parallel.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Runs <count> workers side by side, waits for all of them, prints each one's output in order,`n# and exits with the first failing worker's code, or 0.`n# Usage: sh run-parallel.sh <count> [<worker whose tests use a wrong password>]`ncount=`$1; broken=`${2:-0}; pids=`ni=1`nwhile [ `"`$i`" -le `"`$count`" ]; do`n  password=s3cret; [ `"`$i`" -ne `"`$broken`" ] || password=wrong`n  sh worker.sh `"`$i`" `"`$password`" > `"out-`$i.txt`" 2>&1 &`n  pids=`"`$pids `$!`"`n  i=`$((i + 1))`ndone`n`nstatus=0; i=1`nfor pid in `$pids; do`n  wait `"`$pid`"; code=`$?`n  cat `"out-`$i.txt`"`n  if [ `"`$code`" -ne 0 ]; then`n    echo `"worker `$i failed: exit `$code`"`n    [ `"`$status`" -ne 0 ] || status=`$code`n  fi`n  i=`$((i + 1))`ndone`nexit `"`$status`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'clash.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# What a worker meets when it shares with another: starts one surl over shared/ on a free`n# port, then a second on the same directory or the same port, and exits with the second's code.`n# Usage: sh clash.sh directory|port`n: > first.txt`nsurl --directory shared http://127.0.0.1:0/ > first.txt 2> /dev/null &`nfirst=`$!`ntries=0`nuntil grep -q '^Listening on ' first.txt; do`n  tries=`$((tries + 1)); [ `"`$tries`" -lt 100 ] || break; sleep 0.1`ndone`nurl=`$(sed -n 's|^Listening on ||p' first.txt | tr -d '\r')`nif [ `"`$1`" = directory ]; then surl --directory shared http://127.0.0.1:0/; else surl `"`$url`"; fi`ncode=`$?`nkill `"`$first`"`nexit `"`$code`"`n")
sh run-parallel.sh 4
